{
  "name": "@haowei0520/acp-connector",
  "version": "0.17.1",
  "description": "Single-WebSocket ACP connector: connects local ACP stdio agents (opencode, claude code) to AgentNexus over /ws/acp.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "agentnexus-acp-connector": "dist/cli.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "lint": "tsc -p tsconfig.json --noEmit",
    "test": "npm run build && tsc -p tsconfig.fixtures.json && vitest run",
    "start": "node dist/cli.js run",
    "daemon:start": "node dist/cli.js start",
    "daemon:stop": "node dist/cli.js stop",
    "daemon:restart": "node dist/cli.js restart",
    "daemon:status": "node dist/cli.js status",
    "daemon:logs": "node dist/cli.js logs",
    "prepack": "npm run build",
    "prepublishOnly": "npm run build",
    "test:opencode": "npm run build && node scripts/test-opencode-session-contract.mjs",
    "test:pi": "npm run build && node scripts/test-pi-session-contract.mjs"
  },
  "keywords": [
    "agentnexus",
    "acp",
    "agent-client-protocol",
    "opencode",
    "claude"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Grant-Huang/AgentNexus.git",
    "directory": "packages/agentnexus-acp-connector"
  },
  "bugs": {
    "url": "https://github.com/Grant-Huang/AgentNexus/issues"
  },
  "homepage": "https://github.com/Grant-Huang/AgentNexus/tree/develop/packages/agentnexus-acp-connector#readme",
  "engines": {
    "node": ">=20.6.0"
  },
  "dependencies": {
    "@opentelemetry/api": "1.9.0",
    "@opentelemetry/exporter-trace-otlp-http": "0.219.0",
    "@opentelemetry/resources": "2.8.0",
    "@opentelemetry/sdk-trace-base": "2.8.0",
    "ws": "^8.18.0"
  },
  "devDependencies": {
    "@types/node": "^22.9.0",
    "@types/ws": "^8.5.13",
    "typescript": "~5.6.2",
    "vitest": "^2.1.4"
  }
}
